import{o as a,c as i,a0 as n,j as t,t as l,p as s}from"./chunks/framework.L_oL6aia.js";const d={class:"rock-copy-email-wrapper inline"},u=JSON.parse('{"title":"Midnight Rambler: ユーザーマニュアル","description":"","frontmatter":{},"headers":[],"relativePath":"ja/midnight-rambler.md","filePath":"ja/midnight-rambler.md"}'),g={name:"ja/midnight-rambler.md"},b=Object.assign(g,{setup(c){const r=s("メールアドレスをコピー");function o(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),r.value="コピーしました！",setTimeout(function(){r.value="メールアドレスをコピー"},2e3)}return(m,e)=>(a(),i("div",null,[e[1]||(e[1]=n('<h1 id="midnight-rambler-ユーザーマニュアル" tabindex="-1">Midnight Rambler: ユーザーマニュアル <a class="header-anchor" href="#midnight-rambler-ユーザーマニュアル" aria-label="Permalink to &quot;Midnight Rambler: ユーザーマニュアル&quot;">​</a></h1><p><strong>バージョン 1.0.1</strong></p><p>本マニュアルは、伝説のTweed 5E3アンプ・エミュレーション・ストンプボックスプラグイン <strong>Midnight Rambler</strong> の使用方法、設計思想、および技術仕様について詳しく解説します。</p><img src="/midnightramblerinterface.png" alt="Midnight Rambler GUI" style="max-height:280px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><div style="display:flex;gap:0.75rem;justify-content:center;flex-wrap:wrap;margin:1.25rem 0 1.75rem 0;"><a href="/midnight-rambler-manual.pdf" download class="rock-btn rock-btn-secondary" style="display:inline-flex;align-items:center;justify-content:center;min-width:180px;padding:0.6rem 1.2rem;text-decoration:none;">PDFマニュアルを入手 (v1.0.1) 📄</a><a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/v1.0.1" target="_blank" class="rock-btn rock-btn-primary" style="display:inline-flex;align-items:center;justify-content:center;min-width:220px;padding:0.6rem 1.4rem;text-decoration:none;">プラグインをダウンロード (無料 v1.0.1) ⬇️</a></div><hr><h2 id="_1-tweed-5e3-の魂-スタジオレコーディングの生ける伝説" tabindex="-1">1. Tweed 5E3 の魂：スタジオレコーディングの生ける伝説 <a class="header-anchor" href="#_1-tweed-5e3-の魂-スタジオレコーディングの生ける伝説" aria-label="Permalink to &quot;1. Tweed 5E3 の魂：スタジオレコーディングの生ける伝説&quot;">​</a></h2><p>1950年代の <strong>Fender Tweed Deluxe 5E3</strong> は、ロック史において最も優れたスタジオ録音用アンプとして、多くのプロデューサーやギタリストから絶大な信頼を寄せられています。極めてシンプルな6V6真空管回路は、大型スタジアムアンプでは決して得られない独特のオーガニックなコンプレッション感、豊かな倍音、そして弾き手のタッチに追従するダイナミクスを生み出します。</p><p>ローリング・ストーンズのキース・リチャーズによる伝説的リズムギター（『<em>Sticky Fingers</em>』『<em>Exile on Main St.</em>』）やニール・ヤングの轟くクランチ、ビリー・ギボンズのテキサス・ブルース・バイト、イーグルス『<em>Hotel California</em>』の名演に至るまで、Tweed 5E3 は数え切れないほどの名盤を彩ってきました。</p><h3 id="midnight-rambler-が目指した新基準" tabindex="-1">Midnight Rambler が目指した新基準 <a class="header-anchor" href="#midnight-rambler-が目指した新基準" aria-label="Permalink to &quot;Midnight Rambler が目指した新基準&quot;">​</a></h3><p>平坦で無機質なデジタルモデリングや静的なIRローダーとは異なり、Midnight Rambler はブティック・キャリブレーションされた実機の息づかいとアコースティックな響きをそのまま捉えています：</p><ul><li><strong>リアル・ニューラル・ダイナミクス:</strong> 最先端の Neural Amp Modeler (NAM) ディープニューラルネットワークを採用。ギター側のボリュームノブの絞りや、ピッキングの強弱に忠実に追従します。</li><li><strong>入力保護＆インテリジェント・ノイズ抑制:</strong> 入力段に適応型ノイズゲート（-58 dBFS）とアナログ・ソフトクリッパー（-0.1 dBFS）を内蔵。余計なヒスノイズを排除し、デジタルクリップを音楽的に防ぎます。</li><li><strong>ミックスに即馴染むスタジオ仕様:</strong> State-Variable TPTフィルター（Bass HP &amp; Tone LP）と、1971年製 Oxford 12インチ・スタジオキャビネットのゼロレイテンシー畳み込み（Royer R121リボン＆Shure SM57）を搭載。</li><li><strong>高精度クロマチックチューナー内蔵:</strong> レトロな発光VUメーターとデュアル検出アルゴリズム（YIN / MPM）を備えた高精度チューナーを搭載。</li><li><strong>ゼロレイテンシー＆完全フリー:</strong> アカウント登録不要、ドングル不要、超低CPU負荷。立ち上げてノブを回すだけで、即座に名盤のトーンが得られます。</li></ul><hr><h2 id="_2-コントロール・ガイド" tabindex="-1">2. コントロール・ガイド <a class="header-anchor" href="#_2-コントロール・ガイド" aria-label="Permalink to &quot;2. コントロール・ガイド&quot;">​</a></h2><p>プラグインは4つのメインノブ、3つのロータリースイッチ、そして内蔵クロマチックチューナーで直感的に操作できます：</p><h3 id="🎛️-メインノブ" tabindex="-1">🎛️ メインノブ <a class="header-anchor" href="#🎛️-メインノブ" aria-label="Permalink to &quot;🎛️ メインノブ&quot;">​</a></h3><ul><li><strong>VOLUME / GAIN (<code>1.0</code> 〜 <code>10.0</code>):</strong> 真空管エンジンへの入力ゲインを調整します。低めの設定ではクリスタルなクリーン、高く設定するにつれて太いヴィンテージ・サチュレーションと歌うようなサステインが得られます。</li><li><strong>BASS (HP Filter · <code>20 Hz</code> 〜 <code>300 Hz</code>):</strong> 不要な超低域の濁り（ランブル）をカットし、タイトでパンチのある低域に引き締めます。</li><li><strong>TONE (LP Filter · <code>1.0 kHz</code> 〜 <code>20.0 kHz</code>):</strong> 高域の抜けと存在感を調整し、耳障りな成分を抑えてウッディで温かみのあるトーンに整えます。</li><li><strong>MASTER (<code>1.0</code> 〜 <code>10.0</code>):</strong> クリーンなリニア出力音量。最大 <code>+18 dB</code> のクリーンブーストが可能です。</li></ul><h3 id="🔀-セレクター-スイッチ" tabindex="-1">🔀 セレクター＆スイッチ <a class="header-anchor" href="#🔀-セレクター-スイッチ" aria-label="Permalink to &quot;🔀 セレクター＆スイッチ&quot;">​</a></h3><ul><li><strong>CHANNEL (Edge / Cranked):</strong><ul><li><strong>EDGE:</strong> 繊細なピッキングニュアンスに反応する、歪み始め（Edge-of-breakup）のダイナミックなトーン。</li><li><strong>CRANKED:</strong> パワー管が程よくサチュレートした、太くリッチなヴィンテージ・オーバードライブ。</li></ul></li><li><strong>MIC / CAB (3ポジション・ロータリースイッチ · 1971 Oxford 12&quot; Studio Cabinet):</strong><ul><li><strong>WARM (9時方向):</strong> Royer R121 リボンマイク。中低域が太く滑らかで温かみのあるヴィンテージトーン。</li><li><strong>SHARP (6時方向):</strong> Shure SM57 ダイナミックマイク。アタック感と中高域のバイト感が際立つ抜けの良いトーン。</li><li><strong>BLEND (3時方向):</strong> SM57とR121を 60/40 でブレンドした、奥行きとリアリズムあふれるスタジオ定番セッティング。</li></ul></li><li><strong>STANDBY (Play / Mute):</strong> 出力を瞬時にミュートし、CPU使用率を <strong>0.0%</strong> に下げます。</li><li><strong>TUNER ボタン (右上):</strong> 内蔵の高精度クロマチックチューナー画面を開きます。</li><li><strong>ダイナミックスキン変更:</strong> プラグインウィンドウ上に任意の画像ファイル（<code>.jpg</code> または <code>.png</code>）をドラッグ＆ドロップするだけで、外観をカスタマイズできます。</li></ul><h3 id="📟-高精度クロマチック・vuメーターチューナー" tabindex="-1">📟 高精度クロマチック・VUメーターチューナー <a class="header-anchor" href="#📟-高精度クロマチック・vuメーターチューナー" aria-label="Permalink to &quot;📟 高精度クロマチック・VUメーターチューナー&quot;">​</a></h3><img src="/midnightramblertuner.png" alt="Midnight Rambler Chromatic Tuner" style="max-height:250px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><ul><li><strong>発光アナログVUメーター:</strong> <code>-50</code> から <code>+50 セント</code> の偏差を滑らかな針の動きで表示。チューニングが合うと中央の <code>0</code> マークが鮮やかなグリーンに点灯します。</li><li><strong>デュアルピッチ検出エンジン:</strong><ul><li><strong>MPM (McLeod Pitch Method):</strong> 倍音成分の多いギター信号に強く、素早い音程追従が可能です。</li><li><strong>YIN:</strong> 業界標準の高精度自己相関アルゴリズムで、基音を正確にトラッキングします。</li></ul></li><li><strong>周波数＆ノート表示:</strong> 検出されたノート名（例: <code>E2</code>, <code>A2</code>, <code>D3</code>, <code>G3</code>, <code>B3</code>, <code>E4</code>）と周波数（Hz、$A4 = 440\\text{ Hz}$）を表示。</li><li><strong>Zero-CPU スリープ構造:</strong> チューナー画面を閉じると内部スレッドが完全に休止し、<strong>CPU負荷 0%</strong> を保証します。</li></ul><hr><h2 id="_3-オーディオ設定-スタンドアロン起動時" tabindex="-1">3. オーディオ設定（スタンドアロン起動時） <a class="header-anchor" href="#_3-オーディオ設定-スタンドアロン起動時" aria-label="Permalink to &quot;3. オーディオ設定（スタンドアロン起動時）&quot;">​</a></h2><p>スタンドアロン（単体アプリ）として起動する場合、最適なパフォーマンスを得るために以下の設定を推奨します：</p><ol><li><strong>Audio Device Type:</strong> Windowsではレイテンシーとノイズを防ぐため、必ず <strong>ASIO</strong> を選択してください。</li><li><strong>Device:</strong> お使いのオーディオインターフェースの専用ASIOドライバー（例: <em>Focusrite USB ASIO</em> など）を選択します。</li><li><strong>Sample Rate:</strong> <strong>48000 Hz</strong> (48 kHz) を推奨します。</li><li><strong>Buffer Size:</strong> <strong>128 samples</strong> (約2.3 ms) または <strong>256 samples</strong> (約5.3 ms) に設定します。</li></ol><h4 id="💡-バッファサイズの秘密-なぜ-256-samples-5-3-ms-の方が心地よく聴こえるのか" tabindex="-1">💡 バッファサイズの秘密：なぜ 256 samples (5.3 ms) の方が心地よく聴こえるのか？ <a class="header-anchor" href="#💡-バッファサイズの秘密-なぜ-256-samples-5-3-ms-の方が心地よく聴こえるのか" aria-label="Permalink to &quot;💡 バッファサイズの秘密：なぜ 256 samples (5.3 ms) の方が心地よく聴こえるのか？&quot;">​</a></h4><p>多くのギタリストが、128 samplesよりも256 samplesの方が「音が太く、滑らかに聴こえる」と感じます。これには2つの理由があります：</p><ul><li><strong>プロセッサの安定性:</strong> 256 samplesに設定するとCPU処理にゆとりが生まれ、ごく僅かなマイクロジッターによる高域のチリつきが抑えられます。</li><li><strong>アコースティック・ダブリング効果:</strong> わずか 5.3 ms の遅延は、部屋で生鳴りしているギターの生弦の音とスピーカーからの出音との間で自然な「ダブリング効果」を生み出し、適度な奥行きと立体感をもたらします。</li></ul><hr><h2 id="_4-システム要件-インストール" tabindex="-1">4. システム要件＆インストール <a class="header-anchor" href="#_4-システム要件-インストール" aria-label="Permalink to &quot;4. システム要件＆インストール&quot;">​</a></h2><h3 id="🖥️-システム要件" tabindex="-1">🖥️ システム要件 <a class="header-anchor" href="#🖥️-システム要件" aria-label="Permalink to &quot;🖥️ システム要件&quot;">​</a></h3><ul><li><strong>対応OS</strong>: <ul><li><strong>Windows</strong>: Windows 10 / Windows 11 (64-bit)。</li><li><strong>macOS</strong>: macOS 10.13 以降（Intel および Apple Silicon M1/M2/M3/M4 ネイティブ対応）。</li><li><strong>Linux</strong>: Ubuntu 22.04 以降または互換性のある 64-bit ディストリビューション。</li></ul></li><li><strong>CPU</strong>: WindowsおよびLinuxでは、ニューラルネットワーク演算をリアルタイム処理するために <strong>AVX2</strong> 命令セットをサポートするプロセッサ（Intel 第4世代Core / AMD Ryzen以降）が必要です。Apple Silicon Macはネイティブで完全対応しています。</li><li><strong>メモリ (RAM)</strong>: 最低 4 GB。</li><li><strong>オーディオインターフェース</strong>: 低レイテンシードライバー（Windows: <strong>ASIO</strong>、macOS: <strong>CoreAudio</strong>、Linux: <strong>JACK</strong> / <strong>ALSA</strong>）。</li></ul><h3 id="📦-オールインワン設計" tabindex="-1">📦 オールインワン設計 <a class="header-anchor" href="#📦-オールインワン設計" aria-label="Permalink to &quot;📦 オールインワン設計&quot;">​</a></h3><p><strong>Midnight Rambler は完全自己完結型です。</strong> 外部のモデルファイルやIR wavファイルを個別に読み込む必要はありません：</p><ul><li>すべてのニューラルアンプモデルとキャビネットIRは、プラグインバイナリ内部に<strong>バイナリリソースとして内蔵</strong>されています。</li><li><strong>Windows</strong>: <code>.vst3</code> ファイルをご使用のVST3フォルダ（通常は <code>C:\\Program Files\\Common Files\\VST3\\</code>）にコピーするか、スタンドアロンの <code>.exe</code> を実行してください。</li><li><strong>macOS</strong>: <code>.vst3</code> または <code>.component</code> (AU) をプラグインフォルダ（<code>/Library/Audio/Plug-Ins/VST3/</code> または <code>/Library/Audio/Plug-Ins/Components/</code>）にコピーするか、スタンドアロンの <code>.app</code> を実行してください。</li><li><strong>Linux</strong>: <code>.vst3</code> をプラグインフォルダ（<code>~/.vst3/</code> または <code>/usr/lib/vst3/</code>）に配置してください。</li><li><strong>直接ダウンロード</strong>: <a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/v1.0.1" target="_blank" rel="noreferrer">GitHub Releases</a> から最新のマルチプラットフォーム・バンドルを入手できます。</li></ul><div style="margin:1.25rem 0;text-align:center;"><a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/v1.0.1" target="_blank" class="rock-btn rock-btn-primary" style="display:inline-flex;align-items:center;justify-content:center;min-width:250px;padding:0.65rem 1.6rem;text-decoration:none;font-size:1rem;">Midnight Rambler v1.0.1 をダウンロード (無料) ⬇️</a></div><hr><h2 id="_5-トラブルシューティング" tabindex="-1">5. トラブルシューティング <a class="header-anchor" href="#_5-トラブルシューティング" aria-label="Permalink to &quot;5. トラブルシューティング&quot;">​</a></h2><h3 id="❌-dawでvst3が認識されない・スキャンに失敗する" tabindex="-1">❌ DAWでVST3が認識されない・スキャンに失敗する <a class="header-anchor" href="#❌-dawでvst3が認識されない・スキャンに失敗する" aria-label="Permalink to &quot;❌ DAWでVST3が認識されない・スキャンに失敗する&quot;">​</a></h3><ul><li><strong>Microsoft Visual C++ 再頒布可能パッケージ (Windows)</strong>: プラグインはスタティックリンクされていますが、環境によっては基本的なランタイムが必要な場合があります。公式の <a href="https://aka.ms/vs/17/release/vc_redist.x64.exe" target="_blank" rel="noreferrer">Visual C++ Redistributable 2015-2022 (x64)</a> をインストールしてください。</li><li><strong>CPUのAVX2対応</strong>: お使いのCPUが <strong>AVX2</strong> に対応しているか確認してください。AVX2非対応の古いCPUではNAMニューラルエンジンが動作しません。</li><li><strong>プラグイン配置パス</strong>: DAWのプラグインスキャン対象フォルダに <code>.vst3</code> が正しく配置されているかご確認ください。</li></ul><h3 id="❌-macosで「開発元を検証できないため開けません」と表示される" tabindex="-1">❌ macOSで「開発元を検証できないため開けません」と表示される <a class="header-anchor" href="#❌-macosで「開発元を検証できないため開けません」と表示される" aria-label="Permalink to &quot;❌ macOSで「開発元を検証できないため開けません」と表示される&quot;">​</a></h3><ul><li><strong>原因</strong>: 自動ビルドCIで生成されたバイナリのため、Appleの有料公認証明書による公証（Notarization）が行われていない場合に表示されます。</li><li><strong>解決策</strong>: <strong>システム設定 &gt; プライバシーとセキュリティ</strong> を開き、セキュリティ項目で Midnight Rambler の「<strong>このまま開く</strong>」をクリックしてください。またはターミナルで以下を実行します： <code>xattr -cr /path/to/MidnightRambler.app</code></li></ul><h3 id="❌-プチプチとノイズが入る、またはレイテンシーが大きい" tabindex="-1">❌ プチプチとノイズが入る、またはレイテンシーが大きい <a class="header-anchor" href="#❌-プチプチとノイズが入る、またはレイテンシーが大きい" aria-label="Permalink to &quot;❌ プチプチとノイズが入る、またはレイテンシーが大きい&quot;">​</a></h3><ul><li><strong>オーディオドライバー</strong>: 必ずオーディオインターフェース専用の低レイテンシードライバー（Windows: ASIO）を使用してください。</li><li><strong>バッファサイズ</strong>: <strong>128</strong> または <strong>256 samples</strong> を推奨します。64 samples以下に設定すると、PCスペックによってCPUスパイクや音切れが発生する場合があります。</li></ul><hr><h2 id="_6-ライセンス-利用規約" tabindex="-1">6. ライセンス＆利用規約 <a class="header-anchor" href="#_6-ライセンス-利用規約" aria-label="Permalink to &quot;6. ライセンス＆利用規約&quot;">​</a></h2><p><strong>Midnight Rambler</strong> は <a href="/LICENSE.txt">Main St Audio Labs End User License Agreement (EULA)</a> のもとで <strong>フリーウェア（クローズドソース）</strong> として配布されています：</p><ul><li><strong>自由な利用:</strong> 個人利用、教育目的、商業音楽制作、レコーディング、ライブ演奏などにおいて、ロイヤリティや使用料なしで完全無料でご利用いただけます。</li><li><strong>権利の保護:</strong> リバースエンジニアリング、逆コンパイル、バイナリの再販や有料での再配布は固く禁じられています。</li><li><strong>免責事項:</strong> 本ソフトウェアは現状有姿（AS IS）で提供されます。記載されている第三者のブランド名（<em>Fender</em>, <em>Tweed Deluxe</em>, <em>5E3</em> 等）は、歴史的トーンの識別のためにのみ言及されています。</li></ul><hr><h3 id="あなたのミックスをお待ちしています" tabindex="-1">あなたのミックスをお待ちしています！ <a class="header-anchor" href="#あなたのミックスをお待ちしています" aria-label="Permalink to &quot;あなたのミックスをお待ちしています！&quot;">​</a></h3><p>Midnight Rambler で録音・ミックスした楽曲がございましたら、ぜひお気軽にお聴かせください：</p>',52)),t("div",d,[e[0]||(e[0]=t("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),t("button",{class:"rock-copy-btn",onClick:o},l(r.value),1)]),e[2]||(e[2]=t("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"当ラボの独立開発を応援していただける場合は、Ko-fiまたは仮想通貨でのサポートをお待ちしております：",-1)),e[3]||(e[3]=t("div",null,[t("a",{href:"/ja/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"ラボの開発を支援する（Ko-fi / 仮想通貨） ☕")],-1))]))}});export{u as __pageData,b as default};
